<?php
session_start();include '../koneksi.php';if(!isset($_SESSION['login'])||$_SESSION['role']!='kasir'){header('Location: ../login.php');exit;} $data=mysqli_query($koneksi,"SELECT * FROM produk ORDER BY nama_produk ASC");include 'header.php';
?><div class="container py-4"><div class="mb-4"><h2 class="fw-bold mb-1">Produk</h2><p class="text-secondary mb-0">Cari produk dengan cepat tanpa harus menggulir seluruh daftar.</p></div><div class="card shadow-sm"><div class="card-body"><div class="input-group mb-3"><span class="input-group-text">Cari</span><input type="text" id="cari" class="form-control" placeholder="Cari nama produk..." autocomplete="off"></div><div class="table-responsive"><table class="table table-bordered table-hover" id="produkTable"><thead class="table-dark"><tr><th>No</th><th>Produk</th><th>Harga</th><th>Stok</th></tr></thead><tbody><?php $no=1;while($d=mysqli_fetch_assoc($data)): ?><tr data-nama="<?=htmlspecialchars(strtolower($d['nama_produk']))?>"><td><?=$no++?></td><td><?=htmlspecialchars($d['nama_produk'])?></td><td>Rp <?=number_format($d['harga'],0,',','.')?></td><td><?=$d['stok']?></td></tr><?php endwhile; ?></tbody></table></div><div id="kosong" class="text-center text-secondary d-none py-3">Produk tidak ditemukan.</div></div></div></div><script>document.getElementById('cari').addEventListener('input',function(){let k=this.value.toLowerCase();let n=0;document.querySelectorAll('#produkTable tbody tr').forEach(r=>{let ok=r.dataset.nama.includes(k);r.classList.toggle('d-none',!ok);if(ok)n++;});document.getElementById('kosong').classList.toggle('d-none',n!==0);});</script></body></html>